    const POET_SHAYARI_DATA = {"all": {"name": "Mehfil-e-Rekhta & Kavita Anthology", "pen": "सब शो'रा / कवि (पीयूष मिश्रा • जावेद अख़्तर • दिनकर • मंटो • मिज़ाज)", "couplets": [{"urdu": "کچھ عشق کیا کچھ کام کیا وہ لوگ بہت خوش قسمت تھے\nجو عشق کو کام سمجھتے تھے یا کام سے عاشقی کرتے تھے", "hindi": "कुछ इश्क़ किया कुछ काम किया, वो लोग बहुत ख़ुशक़िस्मत थे\nजो इश्क़ को काम समझते थे या काम से आशिकी करते थे...", "eng": "Some loved, some worked; blessed were those\nwho treated love as their work, or fell in love with their work.", "attr": "— PIYUSH MISHRA (पीयूष मिश्रा)", "ghazal": "कुछ इश्क़ किया कुछ काम किया\nवो लोग बहुत ख़ुशक़िस्मत थे\nजो इश्क़ को काम समझते थे\nया काम से आशिकी करते थे\n\nहम जीते-जी मशरूफ़ रहे\nकुछ इश्क़ किया कुछ काम किया\nकाम इश्क़ के आड़े आता रहा\nऔर इश्क़ से काम उलझता रहा"}, {"urdu": "کیوں ڈریں زندگی میں کیا ہوگا\nکچھ نہ ہوگا تو تجربہ ہوگا", "hindi": "क्यूँ डरें ज़िन्दगी में क्या होगा\nकुछ न होगा तो तजुर्बा होगा।", "eng": "Why fear what will happen in life?\nEven if nothing happens, at least it will be an experience.", "attr": "— JAVED AKHTAR (जावेद अख़्तर)", "ghazal": "क्यूँ डरें ज़िन्दगी में क्या होगा\nकुछ न होगा तो तजुर्बा होगा\n\nहँसती आँखों में झाँक कर देखो\nकोई आँसू कहीं छुपा होगा\n\nहम भी कैसे अजीब मुसाफ़िर हैं\nमंज़िलें हैं मगर पता ग़ुम है"}, {"urdu": "سچ ہے وپتی جب آتی ہے كائر کو ہی دہلاتی ہے\nشورما نہیں وچلت ہوتے كشن ایک نہیں دھیرج كھوتے", "hindi": "सच है, विपत्ति जब आती है, कायर को ही दहलाती है,\nशूरमा नहीं विचलित होते, क्षण एक नहीं धीरज खोते...", "eng": "Truth is, when adversity strikes, it terrifies only the coward.\nThe brave never falter, nor do they lose patience for even a moment.", "attr": "— RAMDHARI SINGH 'DINKAR' (रामधारी सिंह 'दिनकर')", "ghazal": "सच है, विपत्ति जब आती है, कायर को ही दहलाती है,\nशूरमा नहीं विचलित होते, क्षण एक नहीं धीरज खोते,\nविघ्नों को गले लगाते हैं, कांटों में राह बनाते हैं!\n\nहै कौन विघ्न ऐसा जग में, टिक सके वीर नर के मग में?\nखम ठोक ठेलता है जब नर, पर्वत के जाते पांव उखड़,\nमानव जब जोर लगाता है, पत्थर पानी बन जाता है!"}, {"urdu": "اگر آپ میرے افسانوں کو برداشت نہیں کر سکتے\nتو اس کا مطلب ہے کہ زمانہ ہی ناقابلِ برداشت ہے", "hindi": "अगर आप मेरे अफ़सानों को बर्दाश्त नहीं कर सकते,\nतो इसका मतलब है कि ज़माना ही नाक़ाबिले-बर्दाश्त है...", "eng": "If you cannot bear my stories, it means this era is unbearable.\nMy stories merely hold up an honest mirror to society.", "attr": "— SAADAT HASAN MANTO (सआदत हसन मंटो)", "ghazal": "अगर आप मेरे अफ़सानों को बर्दाश्त नहीं कर सकते, तो इसका मतलब है कि ज़माना ही नाक़ाबिले-बर्दाश्त है।\n\nमैं उस सोसायटी की चोली क्या उतारूँगा जो पहले से ही नंगी है... मुझे उसे कपड़े पहनाने की कोशिश भी नहीं करनी चाहिए, क्योंकि यह मेरा काम नहीं, दर्ज़ियों का काम है।"}, {"urdu": "گزرے لمحوں کی صدا آج بھی آتی ہے دل میں\nیاد جب भी वह حسیں शाम پرانی آئی", "hindi": "गुज़रे लम्हों की सदा आज भी आती है दिल में,\nयाद जब भी वो हसीं शाम पुरानी आई...", "eng": "Echoes of passing moments still resonate in my heart\nwhenever memories of that enchanting past evening return.", "attr": "— ASHOK MIZAJ (अशोक मिज़ाज)", "ghazal": "गुज़रे लम्हों की सदा आज भी आती है दिल में\nयाद जब भी वो हसीं शाम पुरानी आई\n\nवक़्त की शाख़ पे बिखरे हुए पत्तों की तरह\nज़िंदगी अपनी भी इक ख़्वाब सुहानी आई"}]}, "mishra": {"name": "Piyush Mishra (पीयूष मिश्रा)", "pen": "इश्क़, बाग़ी कलम और रंगमंच की गूंज", "couplets": [{"urdu": "کچھ عشق کیا کچھ کام کیا وہ لوگ بہت خوش قسمت تھے\nجو عشق کو کام سمجھتے تھے یا کام سے عاشقی کرتے تھے", "hindi": "कुछ इश्क़ किया कुछ काम किया, वो लोग बहुत ख़ुशक़िस्मत थे\nजो इश्क़ को काम समझते थे या काम से आशिकी करते थे...", "eng": "Some loved, some worked; blessed were those\nwho treated love as their work, or fell in love with their work.", "attr": "— PIYUSH MISHRA (पीयूष मिश्रा)", "ghazal": "कुछ इश्क़ किया कुछ काम किया\nवो लोग बहुत ख़ुशक़िस्मत थे\nजो इश्क़ को काम समझते थे\nया काम से आशिकी करते थे\n\nहम जीते-जी मशरूफ़ रहे\nकुछ इश्क़ किया कुछ काम किया\nकाम इश्क़ के आड़े आता रहा\nऔर इश्क़ से काम उलझता रहा"}]}, "akhtar": {"name": "Javed Akhtar (जावेद अख़्तर)", "pen": "सुलगते जज़्बात, तरकश और फ़लसफ़ा", "couplets": [{"urdu": "کیوں ڈریں زندگی میں کیا ہوگا\nکچھ نہ ہوگا تو تجربہ ہوگا", "hindi": "क्यूँ डरें ज़िन्दगी में क्या होगा\nकुछ न होगा तो तजुर्बा होगा।", "eng": "Why fear what will happen in life?\nEven if nothing happens, at least it will be an experience.", "attr": "— JAVED AKHTAR (जावेद अख़्तर)", "ghazal": "क्यूँ डरें ज़िन्दगी में क्या होगा\nकुछ न होगा तो तजुर्बा होगा\n\nहँसती आँखों में झाँक कर देखो\nकोई आँसू कहीं छुपा होगा\n\nहम भी कैसे अजीब मुसाफ़िर हैं\nमंज़िलें हैं मगर पता ग़ुम है"}]}, "dinkar": {"name": "Ramdhari Singh 'Dinkar' (रामधारी सिंह 'दिनकर')", "pen": "राष्ट्रकवि • रश्मिरथी • ओज और पौरुष की अमर वाणी", "couplets": [{"urdu": "سچ ہے وپتی جب آتی ہے كائر کو ہی دہلاتی ہے\nشورما نہیں وچلت ہوتے كشن ایک نہیں دھیرج كھوتے", "hindi": "सच है, विपत्ति जब आती है, कायर को ही दहलाती है,\nशूरमा नहीं विचलित होते, क्षण एक नहीं धीरज खोते...", "eng": "Truth is, when adversity strikes, it terrifies only the coward.\nThe brave never falter, nor do they lose patience for even a moment.", "attr": "— RAMDHARI SINGH 'DINKAR' (रामधारी सिंह 'दिनकर')", "ghazal": "सच है, विपत्ति जब आती है, कायर को ही दहलाती है,\nशूरमा नहीं विचलित होते, क्षण एक नहीं धीरज खोते,\nविघ्नों को गले लगाते हैं, कांटों में राह बनाते हैं!\n\nहै कौन विघ्न ऐसा जग में, टिक सके वीर नर के मग में?\nखम ठोक ठेलता है जब नर, पर्वत के जाते पांव उखड़,\nमानव जब जोर लगाता है, पत्थर पानी बन जाता है!"}]}, "manto": {"name": "Saadat Hasan Manto (सआदत हसन मंटो)", "pen": "अफ़सानानिगार: बेबाक सच और मानवीय त्रासदी", "couplets": [{"urdu": "اگر آپ میرے افسانوں کو برداشت نہیں کر سکتے\nتو اس کا مطلب ہے کہ زمانہ ہی ناقابلِ برداشت ہے", "hindi": "अगर आप मेरे अफ़सानों को बर्दाश्त नहीं कर सकते,\nतो इसका मतलब है कि ज़माना ही नाक़ाबिले-बर्दाश्त है...", "eng": "If you cannot bear my stories, it means this era is unbearable.\nMy stories merely hold up an honest mirror to society.", "attr": "— SAADAT HASAN MANTO (सआदत हसन मंटो)", "ghazal": "अगर आप मेरे अफ़सानों को बर्दाश्त नहीं कर सकते, तो इसका मतलब है कि ज़माना ही नाक़ाबिले-बर्दाश्त है।\n\nमैं उस सोसायटी की चोली क्या उतारूँगा जो पहले से ही नंगी है... मुझे उसे कपड़े पहनाने की कोशिश भी नहीं करनी चाहिए, क्योंकि यह मेरा काम नहीं, दर्ज़ियों का काम है।"}]}, "mizaj": {"name": "Ashok Mizaj (अशोक मिज़ाज)", "pen": "क्लासिकल ग़ज़ल और गुज़रे लम्हों की गूंज", "couplets": [{"urdu": "گزرے لمحوں کی صدا آج بھی آتی ہے دل میں\nیاد جب भी वो हसीं शाम पुरानी आई", "hindi": "गुज़रे लम्हों की सदा आज भी आती है दिल में,\nयाद जब भी वो हसीं शाम पुरानी आई...", "eng": "Echoes of passing moments still resonate in my heart\nwhenever memories of that enchanting past evening return.", "attr": "— ASHOK MIZAJ (अशोक मिज़ाज)", "ghazal": "गुज़रे लम्हों की सदा आज भी आती है दिल में\nयाद जब भी वो हसीं शाम पुरानी आई\n\nवक़्त की शाख़ पे बिखरे हुए पत्तों की तरह\nज़िंदगी अपनी भी इक ख़्वाब सुहानी आई"}]}};
